"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Button } from "@/components/ui/button";
import { ThemeToggle } from "@/components/theme-toggle";

export default function Navigation() {
    const pathname = usePathname();

    return (
        <div className="flex items-center gap-2">
            <Link href="/">
                <Button
                    variant={pathname === "/" ? "default" : "ghost"}
                    size="sm"
                    className={pathname === "/" ? "bg-red-700 hover:bg-red-800 text-white" : ""}
                >
                    Painel Tático
                </Button>
            </Link>
            <Link href="/mapa-estrategico">
                <Button
                    variant={pathname === "/mapa-estrategico" ? "default" : "ghost"}
                    size="sm"
                    className={pathname === "/mapa-estrategico" ? "bg-red-700 hover:bg-red-800 text-white" : ""}
                >
                    Mapa Estratégico
                </Button>
            </Link>
            <div className="h-4 w-px bg-slate-200 dark:bg-zinc-800 mx-1" />
            <ThemeToggle />
        </div>
    );
}
